import re
from dataclasses import dataclass
from datetime import datetime

_UPDATED_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPTED_OUT_VALUES = {"y", "yes", "true", "1"}
_EXT_MARKER = re.compile(r"ext|x|#", re.IGNORECASE)
_DIGITS = "0123456789"


def _normalize_email(raw):
    s = (raw or "").strip()
    lt = s.find("<")
    if lt != -1:
        gt = s.find(">", lt + 1)
        if gt != -1:
            s = s[lt + 1:gt]
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = raw or ""
    m = _EXT_MARKER.search(s)
    if m:
        s = s[:m.start()]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    s = (raw or "").strip()
    m = re.fullmatch(r"([0-9]{4,5})-[0-9]{4}", s)  # ZIP+4, incl. Excel-stripped prefix
    if m:
        s = m.group(1)
    if re.fullmatch(r"[0-9]{4}", s):
        s = "0" + s
    return s if re.fullmatch(r"[0-9]{5}", s) else ""


def _normalize_name(raw):
    s = (raw or "").strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = (raw or "").strip()
    for fmt in _UPDATED_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _normalize_tags(raw):
    return sorted({t.strip().lower() for t in re.split(r"[;,]", raw or "")} - {""})


@dataclass
class _Record:
    pos: int
    first: str
    last: str
    zip_code: str
    email: str      # "" unless valid
    phone: str      # "" unless valid
    source: str     # stripped, lower-cased
    manual: bool
    tags: list
    opted_out: bool
    updated: datetime


def _pick(group, attr):
    """Pick the value of `attr` from the group's rows where it is non-empty:
    prefer source == 'manual', then the most recent `updated`, then the
    earlier input row."""
    candidates = [r for r in group if getattr(r, attr)]
    if not candidates:
        return ""
    best = max(candidates, key=lambda r: (r.manual, r.updated, -r.pos))
    return getattr(best, attr)


def _summarize(group):
    return {
        "first_name": _pick(group, "first"),
        "last_name": _pick(group, "last"),
        "zip": _pick(group, "zip_code"),
        "email": _pick(group, "email"),
        "phone": _pick(group, "phone"),
        "source": _pick(group, "source"),
        "tags": ";".join(sorted({t for r in group for t in r.tags})),
        "opted_out": "Y" if any(r.opted_out for r in group) else "N",
        "updated": max(r.updated for r in group).strftime("%Y-%m-%d"),
    }


def dedupe_contacts(rows):
    # Step 1: normalize each row; drop rows with no valid email or phone.
    records = []
    for pos, row in enumerate(rows):
        email = _normalize_email(row.get("email"))
        if not _is_valid_email(email):
            email = ""
        phone = _normalize_phone(row.get("phone"))
        if not _is_valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue
        source = (row.get("source") or "").strip().lower()
        records.append(_Record(
            pos=pos,
            first=_normalize_name(row.get("first_name")),
            last=_normalize_name(row.get("last_name")),
            zip_code=_normalize_zip(row.get("zip")),
            email=email,
            phone=phone,
            source=source,
            manual=(source == "manual"),
            tags=_normalize_tags(row.get("tags")),
            opted_out=(row.get("opted_out") or "").strip().lower() in _OPTED_OUT_VALUES,
            updated=_parse_updated(row.get("updated")),
        ))

    # Step 2: union-find over matching rows (transitive).
    parent = list(range(len(records)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    first_by_email = {}
    first_by_phone_last = {}
    for i, rec in enumerate(records):
        if rec.email:
            if rec.email in first_by_email:
                union(i, first_by_email[rec.email])
            else:
                first_by_email[rec.email] = i
        if rec.phone and rec.last:
            key = (rec.phone, rec.last.lower())
            if key in first_by_phone_last:
                union(i, first_by_phone_last[key])
            else:
                first_by_phone_last[key] = i

    # Step 3: group rows by person. Dict insertion order follows each
    # group's earliest input row, since records are in input order.
    groups = {}
    for i, rec in enumerate(records):
        groups.setdefault(find(i), []).append(rec)

    return [_summarize(group) for group in groups.values()]
```

Notes for the send:

- **Opted-out people are still in the output**, flagged `opted_out: "Y"`. Filter those out before building the send list, or the email will go to people who opted out.
- **ZIP+4 handling:** I read "looks like ZIP+4" as a 4- or 5-digit prefix, a hyphen, and a 4-digit suffix. That way "2139-4307" becomes "02139", matching the leading-zero rule. If your data person meant something stricter, change the regex in `_normalize_zip`.
- **Bad `updated` values raise `ValueError`** with the offending value instead of being silently ranked. That's deliberate: a malformed date would otherwise change which row wins a field, and nobody would notice. Find out which rows fail before the function runs if you want to avoid a crash.
- Rows with no valid email or phone are dropped before matching, so they never reach the output and can't be emailed.
